window.ScripturaLexicons.BDAG_PART_0061 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:" <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-basanismos-bdag\" data-source=\"BDAG\" data-search=\"βασανισμός, οῦ, ὁ basanismós substantivo masculino tortura; tormento; sofrimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βασανισμός, οῦ, ὁ</td><td>substantivo masculino</td><td>tortura; tormento; sofrimento</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-basanistes-bdag\" data-source=\"BDAG\" data-search=\"βασανιστής, οῦ, ὁ basanistḗs substantivo masculino carcereiro opressor; torturador BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βασανιστής, οῦ, ὁ</td><td>substantivo masculino</td><td>carcereiro opressor; torturador</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-basanos-bdag\" data-source=\"BDAG\" data-search=\"βάσανος, ου, ἡ básanos substantivo feminino tortura; tormento; dor intensa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βάσανος, ου, ἡ</td><td>substantivo feminino</td><td>tortura; tormento; dor intensa</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-basileia-bdag\" data-source=\"BDAG\" data-search=\"βασιλεία, ας, ἡ basileía substantivo feminino realeza; governo régio; reinado; reino; território governado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βασιλεία, ας, ἡ</td><td>substantivo feminino</td><td>realeza; governo régio; reinado; reino; território governado</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-basileios-bdag\" data-source=\"BDAG\" data-search=\"βασίλειος, ον basíleios adjetivo; substantivo por substantivação régio; real; palácio; reino BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βασίλειος, ον</td><td>adjetivo; substantivo por substantivação</td><td>régio; real; palácio; reino</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-basileus-bdag\" data-source=\"BDAG\" data-search=\"βασιλεύς, έως, ὁ basileús substantivo masculino rei; soberano; governante; rei messiânico BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βασιλεύς, έως, ὁ</td><td>substantivo masculino</td><td>rei; soberano; governante; rei messiânico</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-basileuo-bdag\" data-source=\"BDAG\" data-search=\"βασιλεύω basileúō verbo ser rei; reinar; dominar; tornar-se rei BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βασιλεύω</td><td>verbo</td><td>ser rei; reinar; dominar; tornar-se rei</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-basilikos-bdag\" data-source=\"BDAG\" data-search=\"βασιλικός, ή, όν basilikós adjetivo; substantivo real; régio; oficial do rei BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βασιλικός, ή, όν</td><td>adjetivo; substantivo</td><td>real; régio; oficial do rei</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-basiliskos-bdag\" data-source=\"BDAG\" data-search=\"βασιλίσκος, ου, ὁ basilískos substantivo masculino reizinho; pequeno rei BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βασιλίσκος, ου, ὁ</td><td>substantivo masculino</td><td>reizinho; pequeno rei</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-basilissa-bdag\" data-source=\"BDAG\" data-search=\"βασίλισσα, ης, ἡ basílissa substantivo feminino rainha BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βασίλισσα, ης, ἡ</td><td>substantivo feminino</td><td>rainha</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-basis-bdag\" data-source=\"BDAG\" data-search=\"βάσις, εως, ἡ básis substantivo feminino pé; base para pisar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βάσις, εως, ἡ</td><td>substantivo feminino</td><td>pé; base para pisar</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-baskaino-bdag\" data-source=\"BDAG\" data-search=\"βασκαίνω baskaínō verbo enfeitiçar pelo mau-olhado; invejar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βασκαίνω</td><td>verbo</td><td>enfeitiçar pelo mau-olhado; invejar</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-baskania-bdag\" data-source=\"BDAG\" data-search=\"βασκανία, ας, ἡ baskanía substantivo feminino inveja BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βασκανία, ας, ἡ</td><td>substantivo feminino</td><td>inveja</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-baskanos-bdag\" data-source=\"BDAG\" data-search=\"βάσκανος, ου, ὁ báskanos substantivo masculino; adjetivo invejoso; pessoa invejosa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βάσκανος, ου, ὁ</td><td>substantivo masculino; adjetivo</td><td>invejoso; pessoa invejosa</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bassos-bdag\" data-source=\"BDAG\" data-search=\"Βάσσος, ου, ὁ Bássos nome próprio masculino Basso; nome próprio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Βάσσος, ου, ὁ</td><td>nome próprio masculino</td><td>Basso; nome próprio</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bastazo-bdag\" data-source=\"BDAG\" data-search=\"βαστάζω bastázō verbo erguer; carregar; suportar; levar; remover; furtar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βαστάζω</td><td>verbo</td><td>erguer; carregar; suportar; levar; remover; furtar</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-batos-i-bdag\" data-source=\"BDAG\" data-search=\"βάτος, ου, ἡ, ὁ bátos substantivo feminino ou masculino sarça; arbusto espinhoso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βάτος, ου, ἡ, ὁ</td><td>substantivo feminino ou masculino</td><td>sarça; arbusto espinhoso</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-batos-ii-bdag\" data-source=\"BDAG\" data-search=\"βάτος, ου, ὁ bátos substantivo masculino bato; medida hebraica para líquidos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βάτος, ου, ὁ</td><td>substantivo masculino</td><td>bato; medida hebraica para líquidos</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-batrachos-bdag\" data-source=\"BDAG\" data-search=\"βάτραχος, ου, ὁ bátrachos substantivo masculino rã BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βάτραχος, ου, ὁ</td><td>substantivo masculino</td><td>rã</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-battalogeo-bdag\" data-source=\"BDAG\" data-search=\"βατταλογέω battalogéō verbo tagarelar; repetir palavras irrefletidamente; falar sem pensar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">βατταλογέω</td><td>verbo</td><td>tagarelar; repetir palavras irrefletidamente; falar sem pensar</td><td><span class=\"source-pill\">BDAG</span></td></tr>", cardsHtml:" <article id=\"entry-basanismos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βασανισμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦basanismós⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver βασανίζω; Alexis, Com. 290 [em Ateneu 1, 56, p. 30s.]; 4Mc 9:6; 11:2.)<br/><strong>1. Imposição de sofrimento ou dor intensa relacionada à tortura ou ao tormento: ato de atormentar, tortura</strong>, Ap 9:5b.<br/><strong>2. Dor intensa experimentada por meio da tortura: tormento</strong>, versículo 5a; Ap 14:11; 18:10, 15; com πένθος, «luto», versículo 7. Sinônimo: βάσανος. — TW.</p></section></article> <article id=\"entry-basanistes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βασανιστής, οῦ, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦basanistḗs⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Desde Antifonte e Demóstenes 37, 40; também Plutarco, Mor. 498d; TestAbr A e B; Fílon, Spec. Leg. 4, 82; Omn. Prob. Lib. 108; In Flacc. 96.) <strong>Guarda de prisão, frequentemente incumbido de torturar os prisioneiros; carcereiro opressor</strong>, Mt 18:34, onde o sentido «carcereiro impiedoso» parece exigido. Pode estar subjacente a imagem de um rico proprietário de terras que dispunha de lugar de detenção para escravos insubordinados (SEG VIII, 246, 8 [século II d.C.] emprega βασανίζω acerca do tratamento de um devedor de quem se deveria extrair tudo quanto possível); MPol 2:3; ἄγγελοι β., «anjos vingadores», ApcPt 8, 23. — DELG, s.v. βάσανος; TW.</p></section></article> <article id=\"entry-basanos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βάσανος, ου, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦básanos⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Teógnis, Píndaro e posteriores; originalmente «pedra de toque, prova», depois procedimentos ou «tormentos» para obter confissão; inscrições; papiros; Septuaginta; En; TestSol 1:3; Fílon; Josefo, Ant. 12, 255; 13, 241; Justino.)<br/><strong>1. Dor intensa ocasionada por tortura punitiva: tortura, tormento</strong> (Herodas 2, 88, e Diodoro Sículo 15, 58, 2, de tortura ordenada judicialmente para extorquir uma confissão; SIG 780, 12; PLille 29 I, 22; Septuaginta, especialmente frequente em 4Macabeus; Fílon, De Jos. 86; Josefo, Bell. 1, 635; Ant. 16, 245), MPol 2:3, 4; Ox 840, 7. Dos tormentos no mundo inferior (compare Sb 3:1; 4Mc 13:15), e como sinônimo de «fogo inextinguível», 2Cl 17:7b; ὑπάρχειν ἐν β., «estar em tormento», Lc 16:23. Designando lugar no mundo inferior: τόπος τῆς β., «lugar de tormento», versículo 28; compare 2Cl 10:4. Das perseguições aos cristãos, 1Cl 6:1; 2Cl 17:7a. Compare Hv 3, 7, 6; Hs 6, 3, 4; 6, 4, 3s.; 6, 5, 1; 3; 7.<br/><strong>2. Em geral, dor intensa causada por algo opressivo: dor intensa, tormento</strong> (com νόσοι, «doenças»; compare Sexto Empírico, Eth. 153 [Adv. Math. 11, 153]; 1Mc 9:56; Fílon, Abr. 96), Mt 4:24. — Papias 3:3. — P. duBois, Torture and Truth, 1991; B. 1115; DELG; M-M; TW.</p></section></article> <article id=\"entry-basileia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βασιλεία, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦basileía⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Heráclito, fragmento 52; Heródoto e posteriores.) Termo relativo à administração régia.<br/><strong>1. Ato de governar.</strong> <strong>a. Em geral: realeza, poder real, governo régio, reinado</strong> (1Sm 15:28; 20:31; Sir 10:8; Jt 1:1; Et 3:6; 1Mc 1:16 e outros na Septuaginta; En 98:2; TestJob 33:9; Justino; Taciano; Atenágoras; οὐ βασιλείαν ἀλλὰ τυράνιδα, «não realeza, mas tirania», Melitão, P. 49, 354; Orígenes). λαβεῖν ἑαυτῷ βασιλείαν, «obter poder régio para si», Lc 19:12, 15; sem dativo, Ap 17:12 (compare Josefo, Ant. 13, 220); δοῦναί τινι τὴν β., «dar a alguém o poder régio», versículo 17; ἔχειν β. ἐπί τινων, «exercer domínio sobre alguns», versículo 18; ἐποίησεν ἡμᾶς βασιλείαν, «conferiu-nos jurisdição régia», Ap 1:6; compare 5:10; «reinado», Lc 1:33; 22:29; 23:42, variante de leitura (ἐν τῇ β. σου, «no teu poder régio»); At 1:6; Hb 1:8 (Sl 44:7); 1Co 15:24 (παραδιδόναι, como Diodoro Sículo 1, 43, 6); B 4:4 (Dn 7:24). Sl 95:10 (Justino, A I, 41, 4; D. 73: ὁ κύριος ἐβασίλευσεν ἀπὸ τ. ξύλου, «o Senhor reinou a partir do madeiro») fundamenta β. Ἰησοῦ ἐπὶ ξύλου, «o reinado de Jesus na cruz», B 8:5 (ver Windisch, comentário). — Hb 11:33; 1Cl 61:1.<br/><strong>b. Especialmente do governo de Deus: reinado régio de Deus</strong> (habitualmente traduzido «reino de Deus» e frequentemente entendido como domínio territorial, com consequente atenuação do componente primário da atividade de reinar), conceito predominantemente escatológico, que começa a aparecer nos profetas, desenvolve-se nas passagens apocalípticas (Mq 4:7s.; Sl 102:19; 144:11–13; Sb 6:4; 10:10; Dn 3:54; 4:3; compare SibOr 3:47s. — Em Diodoro Sículo 5, 71, 1, Zeus recebe a βασιλεία de Cronos; Sexto 311: κοινωνεῖ βασιλείας θεοῦ σοφὸς ἀνήρ, «o homem sábio participa do reino de Deus») e é ensinado por Jesus. As expressões variam: β. τοῦ θεοῦ e β. τῶν οὐρανῶν têm essencialmente o mesmo sentido, pois os israelitas empregavam οὐρανός (ou οὐρανοί) e outras perífrases para θεός (compare Mt 19:23s.; Bousset, Rel.³, 314s.); a última também pode realçar a origem e a natureza celestes do reinado. — Dalman, Worte 75–119; J. Weiss, D. Predigt Jesu v. Reiche Gottes², 1900, 1–35; E. Sellin, D. isr.-jüd. Heilandserwartung, 1909; D. alt. Prophetismus, 1912, 136ss.; B. Duhm, D. kommende RG, 1910; S. Mowinckel, Psalmenstudien II, 1922, 146ss.; L. Dürr, Ursprung u. Ausbau d. isr. Heilandserwartung, 1925; Bousset, Rel.³, 1926, 213ss.; A. v. Gall, βασιλεία τ. θεοῦ, 1926; J. Wissing, Het begrip van het Koningrijk Gods, dissertação, Leiden, 1927; H. Gressmann, Der Messias, 1929; M. Buber, Königtum Gottes, 1932; P. Volz, D. Eschatologie der jüd. Gemeinde im ntl. Zeitalter, 1934; Lietzmann, D. Weltheiland, 1909; T. Manson, The Teaching of Jesus, 1955, 116–284; S. Aalen, NTS 8, 1961/62, 215–40 («casa» ou «comunidade» de Deus); G. Ladd, JBL 81, 1962, 230–38 («domínio»); F. Nötscher, Vom A. zum NT, 1962, 226–30 (sentido ético).<br/>α. β. τῶν οὐρανῶν, «reino dos céus», principalmente em Mateus: 3:2; 4:17; 5:3, 10, 19s. e outros; noutros lugares (Did., Gen. 52, 11; 60, 28), Jo 3:5, variante de leitura; AcPl Ha 8, 31. β. β. τοῦ θεοῦ, «reino de Deus» (compare Orígenes, C. Cels. 3, 40, 21), Mt 6:33; 12:28; 21:31, 43; Mc 1:15; 4:11, 26, 30 e outros; Lc 4:43; 6:20; 7:28; 8:1 e outros; At 1:3; 8:12; 14:22; 19:8; 28:23, 31; Jo 3:3, 5; Rm 14:17 (definido como δικαιοσύνη, εἰρήνη, χαρά, «justiça, paz, alegria»); 1Co 4:20 e outros; Ox 1, verso, 7s.; Dg 9:1; B 21:1; Pol 2:3; β. θεοῦ, «reino de Deus», 1Co 6:10, compare versículo 9; 15:50; Gl 5:21; Pol 5:3; β. τοῦ Χριστοῦ καὶ θεοῦ, «reino de Cristo e de Deus», Ef 5:5; τοῦ Χριστοῦ, «de Cristo», 1Cl 50:3. γ. β. τοῦ πατρός, «reino do Pai», Mt 13:43; 26:29. δ. β. αὐτοῦ (= τοῦ υἱοῦ τοῦ ἀνθρώπου), «seu reino» (= «do Filho do Homem»), Mt 13:41; Lc 24:26, variante de leitura; compare Cl 1:13. ε. β. τοῦ πατρὸς ἡμῶν Δαυίδ, «reino de nosso pai Davi», Mc 11:10, visto que o reino davídico deverá ser restabelecido sob o Filho de Davi, o Messias (compare Is 9:5s.; Jr 23:5s.). ζ. ἡ β. τοῦ κυρίου, «o reino do Senhor», B 4:13; ἡ β. αὐτοῦ (= κυρίου) ἡ ἐπουράνιος, «seu reino celestial», 2Tm 4:18; EpilMosq 5; ἡ οὐράνιος β., MPol 22:3; ἡ ἐν οὐρανῷ β., Dg 10:2. η. αἰώνιος β. τοῦ κυρίου, «reino eterno do Senhor» (compare Dn 4:3; Justino; CIG II, 2715a, 3: ἐπὶ τῆς τῶν κυρίων Ῥωμαίων αἰωνίου ἀρχῆς, Deissmann, B 277s.), 2Pe 1:11; compare MPol 20:2.<br/>No reino encontram-se as maiores bênçãos concebíveis, Mt 13:44s. As seguintes expressões referem-se a obtê-lo, isto é, participar de seus benefícios: ἅψασθαι τῆς β., «alcançar o reino», B 7:11; δέχεσθαι, «receber», Mc 10:15; διδόναι, «dar», Lc 12:32; εἰσέρχεσθαι εἰς τὴν β., «entrar no reino», Mt 5:20; 7:21; 18:3; 19:23; Mc 10:23ss.; Lc 24:26, P 75 (primeira mão); Jo 3:5; At 14:22; Hs 9, 12, 3s. (H. Windisch, D. Sprüche v. Eingehen in d. Reich Gs, ZNW 27, 1928, 163–92); εἰσήκειν εἰς τὴν β., 2Cl 11:7; ἔρχεσθαι εἰς τὴν β., 2Cl 9:6; ἑτοιμάζειν, «preparar», Mt 25:34; εὔθετον εἶναι τῇ β., «ser apto para o reino», Lc 9:62; εὑρεθῆναι εἰς τὴν β., Hs 9, 13, 2; ζητεῖν, «buscar», Mt 6:33; Lc 12:31; καταξιοῦσθαι τῆς β., «ser julgado digno do reino», 2Ts 1:5; κατοικεῖν ἐν τῇ β., Hs 9, 29, 2; κληρονομεῖν, «herdar», Mt 25:34; 1Co 6:9s.; 15:50; IPhld 3:3; compare κληρονόμος τῆς β., «herdeiro do reino», Tg 2:5; μαθητεύεσθαι τῇ β., «ser instruído para o reino», Mt 13:52; μεθιστάναι εἰς τὴν β., «transferir para o reino», Cl 1:13; φθάνει ἡ β. ἐπί τινα, «o reino alcança alguém», Lc 11:20. ὁρᾶν τὴν β., «ver o reino», isto é, «constatar o cumprimento das promessas de Deus a Israel», Mc 9:1; Lc 9:27; Jo 3:3; Hs 9, 15, 3. Os mistérios do reino podem ser revelados àqueles a quem se destinam, Mt 13:11; Mc 4:11; διαγγέλλειν, «anunciar», Lc 9:60; διαμαρτυρεῖσθαι, «testificar solenemente», At 28:23; κηρύσσειν καὶ εὐαγγελίζεσθαι, «pregar e anunciar boas-novas», Lc 8:1; semelhantemente 16:16; compare κηρύσσειν τὸ εὐαγγέλιον τῆς β., «pregar o evangelho do reino», Mt 4:23; 9:35; 24:14; κηρύσσειν τὴν β., Lc 9:2; At 28:31; λαλεῖν περὶ τῆς β., «falar acerca do reino», Lc 9:11. Impedir a entrada: κλείειν, «fechar», Mt 23:13; compare κλεῖδες τῆς β., «chaves do reino», 16:19 (ver κλεῖς 1); αἴρειν ἀπό τινος, «tirar de alguém», 21:43.<br/>É descrito como presente em Mt 12:28; Lc 11:20, talvez também 17:20s. (ver ἐντός). É considerado futuro, mas próximo: ἤγγικεν ἡ β., «o reino se aproximou», Mt 3:2; 10:7; Mc 1:15; Lc 10:9, 11; talvez Mc 1:15; ἐγγύς ἐστιν, «está próximo», Lc 21:31; ἔρχεται, «vem», Mt 6:10; Mc 11:10; Lc 11:2; 17:20; μέλλει ἀναφαίνεσθαι, «está para manifestar-se», Lc 19:11; προσδέχεσθαι τὴν β., «esperar o reino», Mc 15:43; ἐκδέχεσθαι τὴν β., 2Cl 12:1; μέλλει ἔρχεσθαι, 1Cl 42:3; ἡ μέλλουσα β., «o reino vindouro», 2Cl 5:5; ἥξει ἡ β., «o reino chegará», 2Cl 12:2. Concebido como banquete (Billerbeck IV, 1154ss.): ἀνακλιθῆναι ἐν τῇ β., «reclinar-se à mesa no reino», Mt 8:11; semelhantemente 26:29; Mc 14:25; Lc 13:28s.; 22:16, 18, 30; compare as parábolas de Lc 14:15ss.; Mt 22:2ss. Os participantes são chamados υἱοὶ τῆς β., «filhos do reino», Mt 8:12 (vínculo meramente externo); 13:38. A condição para participar é μετάνοια, «arrependimento», Mt 4:17; Mc 1:15, e a disposição de tornar-se como criança, Mt 18:3s.; 19:14; Mc 10:14s.; Lc 18:16s. Só a retidão herdará o reino, Mt 5:20. Graus e categorias, 5:19; 18:1, 4. Os ricos têm dificuldade para entrar, 19:23s.; Mc 10:23–25; Lc 18:24s. (compare versículo 29), enquanto aqueles que persistem no pecado não têm perspectiva de entrada, Mt 13:24ss., 36ss., 47ss. — Paulo concebe o reino como algo que efetua mudanças nas pessoas, produzindo justiça, paz (com Deus) e alegria, Rm 14:17. Manifesta-se em ações, não em palavras, 1Co 4:20. Os que persistem no pecado não o herdarão, 6:9s.; Gl 5:21; Ef 5:5 (compare 2Cl 9:6); essas passagens mostram que para Paulo o reino é essencialmente futuro, pois os cristãos aguardam a vitória completa do espírito sobre a carne. Compare ainda 2Tm 4:1. Carne e sangue não o herdarão, isto é, para entrar são necessários corpos sob a direção do Espírito de Cristo, 1Co 15:50 (J. Jeremias, NTS 2, 1956, 151–59). Ninguém senão Deus chama as pessoas para o reino, 1Ts 2:12. — H. J. Westerink, Het Koninkrijk Gods bij Pls, 1937. — Literatura mais importante até 1931 em P. Feine, Theol. d. NTs⁷, 1936, 73. Bibliografia adicional: G. Gloege, Reich Gs u. Kirche im NT, 1929; R. Frick, D. Gesch. des R.-Gs-Gedankens in d. alten Kirche, 1929; E. Scott, The Kgdm. of God in the NT, 1931; H.-D. Wendland, Reichsidee u. Gottesreich, 1934; R. Otto, Reich Gottes u. Menschensohn, 1934 (tradução inglesa, The Kgdm. of God and the Son of Man, por Filson e Woolf, 1943 e 1951); TW I, 562–95; W. Kümmel, D. Eschatologie der Evangelien, 1936; Verheissg. u. Erfüllg., 1945 e 1953; J. Héring, Le Royaume de Dieu et sa Venue (Jesus, Paul), 1938 e 1959; J. Theissing, D. Lehre Jesu v. d. ew. Seligkeit, 1940; F. Grant, The Gospel of the Kgdm., 1940; J. Wellhagen, Anden och Riket, 1941 (Lucas); W. Michaelis, D. Herr verzieht nicht d. Verheissung, 1942; R. Liechtenhan, D. Kommen des RGs nach dem NT, 1944; G. Knight, From Moses to Paul, 1949, 173–87; W. Arndt, CTM 21, 1950, 8–29; J. Bright, The Kgdm. of God: The Biblical Concept and Its Mng. for the Church, 1953; R. Schnackenburg, Gottes Herrschaft u. Reich⁴, 1965, tradução J. Murray², 1968; E. Ladd, Jesus and the Kgdm., 1964; N. Perrin, The Kgdm. of God in the Teaching of Jesus, 1966; M. Wolter, NTS 41, 1995, 541–63 (Lucas). — Contexto veterotestamentário: W. Schmidt, Königtum Gottes in Ugarit u. Israel, 1961; K. Bernhardt, D. Problem der altorientalischen Königs-Ideologie im AT, VetusT Suppl. 8, 1961. — Patrística: G. Lampe, JTS 49, 1948, 58–73.<br/><strong>2. Território governado por um rei: reino</strong> (Diodoro Sículo 4, 68, 4; Apiano, Mithrid. 105 §496: ἡ βας. ὅλη, «o reino inteiro»; OGI 383, 25 [século I a.C.]; Sl 67:33; 134:11; Bar 2:4; Tb 1:21; 1Mc 1:6; 3:27; 2Mc 9:25; 3Mc 6:24 e outros na Septuaginta), Mt 12:25s.; 24:7; Mc 3:24; 6:23 (Socrat., Ep. 1, 10: τ. βασιλείας μέρος διδόναι, «dar uma parte do reino»); 13:8; Lc 11:17s.; 21:10; αἱ β. τοῦ αἰῶνος τούτου, «os reinos deste século», IRo 6:1. Na narrativa da tentação, Mt 4:8; Lc 4:5 (de modo bem diverso de Jesus, Alexandre, conforme Diodoro Sículo 17, 51, 2, solicita a seu pai Zeus Amom τὴν ἁπάσης τῆς γῆς ἀρχήν, «domínio sobre toda a terra», e é atendido). — EDNT; DELG, s.v. βασιλεύς; M-M; TW; Spicq; Sv.</p></section></article> <article id=\"entry-basileios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βασίλειος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦basíleios⟧</span><span class=\"separator\">·</span><span>adjetivo; substantivo por substantivação</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Homero e posteriores; Septuaginta; PsSol 17:4, 6; TestSol 5:5; TestJud.) <strong>Pertencente a um rei: real, régio</strong> (oráculo em Diodoro Sículo 7, 17: κράτος βασίλειον, «poder real»); β. ἱεράτευμα, «sacerdócio real», 1Pe 2:9 (Êx 19:6; 23:22; mas ver J. Elliott, The Elect and the Holy, 1966, 149–54). Empregado como substantivo, o plural τὰ β. (desde Heródoto 1, 30, 1; também SIG 495, 45; PSI 488, 11; PColZen 39, 8; PCairZen 664, 1; 758, 7 [todos do século III a.C.]; PGM 2, 181; 4, 1061–62; Et 1:9; Fílon, In Flacc. 92; Josefo, Ant. 13, 138) e, mais raramente, o singular τὸ β. (Xenofonte, Cyr. 2, 4, 3; Pv 18:19; PsSol [«majestade real», também TestSol e TestJud]; Fílon, Sobr. 66; Josefo, Ant. 6, 251) significam <strong>palácio (real)</strong>, Lc 7:25. — Em 2Cl, τὸ β. equivale a ἡ βασιλεία (B-D-F §50; compare TestJud 17:6, 22s.; SibOr 3, 159; Justino, A I, 32, 2; D. 31, 5 [Dn 7:22]; Gaio em Eusébio, HE 3, 28, 2; Polieno 8, 55 usa o plural τὰ βασίλεια = ἡ βασιλεία): εἰσέρχεσθαι εἰς τὸ β. τοῦ θεοῦ, «entrar no reino de Deus», 2Cl 6:9; ὁρᾶν τὸ β. τοῦ κόσμου, «ver o reino do mundo», 2Cl 17:5. — DELG, s.v. βασιλεύς; M-M; TW; Spicq.</p></section></article> <article id=\"entry-basileus-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βασιλεύς, έως, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦basileús⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Homero e posteriores; empréstimo na literatura rabínica.)<br/><strong>1. Quem governa, ocupando a magistratura suprema num território político: rei</strong>; em geral, governante masculino que detém autoridade incontestada (excetuados os governantes-clientes que devem seu poder ao favor de Roma) numa área específica. ποιεῖν τινα β., «fazer alguém rei», Jo 6:15. βασιλεῖς τῆς γῆς, «reis da terra», Mt 17:25; Ap 1:5; 6:15 (Sl 2:2; 88:28), entre outros; At 4:26 (Sl 2:2). β. τῶν ἐθνῶν, «reis das nações», Lc 22:25; com ἡγεμόνες (compare ἡγούμενοι ἐθνῶν καὶ β., Orígenes, C. Cels. 2, 32, 22), Mt 10:18; Mc 13:9; Lc 21:12. De reis em geral (com προφῆται, «profetas», 2Mc 2:13; Boll 139), Lc 10:24. Do faraó, At 7:10 (Taciano 38, 1); de Davi, Mt 1:6; At 13:22 (Justino, A I, 35, 6); de Herodes I (Josefo, Ant. 14, 382, 385; OGI 414, 2; 415, 1; 416, 2; 417, 3; Justino, A I, 40, 6; D. 78, 1), Mt 2:1, 3; Lc 1:5; de Herodes Antipas (não propriamente rei [Josefo, Ant. 17, 188; OGI 414, 2; 415, 1; 416, 2; 417, 3], mas ocasionalmente assim chamado, por exemplo Cícero, Verr. 4, 27), Mt 14:9; Mc 6:14; GPt 1:2 (ASyn. 341, 20); de Herodes Agripa I (Josefo, Ant. 18, 237; 19, 274; OGI 418, 1; 419, 1; 428, 4), At 12:1; de Agripa II (Josefo, Bell. 2, 223; OGI 419, 2; 423, 1; 425, 3; 426, 2), At 25:13, 24, 26; de Aretas, rei dos nabateus, 2Co 11:32; de Melquisedeque, rei de Salém, Hb 7:1s. (Gn 14:18). Do imperador romano (Apiano, Iber. 102 §444; Bell. Civ. 2, 86 §362: Ῥωμαίων β. Ἁδριανός e outros; Herodiano 2, 4, 4; IG III, 12, 18; CIG II, 2721, 11; POxy 33 II, 6; 35 verso, 1; BGU 588, 10; PGM 4, 2448: Ἁδριανὸς β.; 2452; Josefo, Bell. 3, 351; 4, 596; 5, 563; Vi. 34; Magie 62; βασιλεῦ, Ar. 1, 1 e outros; Taciano 4, 1; 19, 1; Melitão, HE 4, 26, 6), 1Tm 2:2 (o plural é genérico, como em Apiano, Prooem. 15 §62; Josefo, Ant. 2, 71; PEg 2, 48; sobre o tema, L. Biehl, D. liturg. Gebet für Kaiser u. Reich, 1937); 1Pe 2:13, 17 (ver Pv 24:21, especialmente Vi. Aesopi I, capítulo 26, p. 288, 17 Eberh.: τέκνον, πρὸ πάντων σέβου τὸ θεῖον, τὸν βασιλέα δὲ τίμα); Ap 17:9; 1Cl 37:3.<br/><strong>2. Quem possui poder extraordinário ou transcendente</strong>, extensão da acepção 1 (Élio Aristides 46, p. 285 D.: β. Θεμιστοκλῆς, «rei Temístocles»). <strong>a. Do rei messiânico:</strong> β. τῶν Ἰουδαίων, «rei dos judeus» (assim Alexandre Janeu: Josefo, Ant. 14, 36; Herodes 16, 311; Aristóbulo, Diodoro Sículo 40, 2), Mt 2:2; 27:11, 29, 37; Mc 15:2, 9, 12, 18, 26; Lc 23:3, 37s.; Jo 18:33 e outros; β. (τοῦ) Ἰσραήλ, «rei de Israel», Mt 27:42; Mc 15:32; Jo 1:49; 12:13; GPt 3:7 (ASyn. 341, 20); 4:11 (ASyn. 344, 74). Daí, Jesus como rei dos cristãos (Orígenes, C. Cels. 1, 61, 27; Did., Gen. 215, 10), MPol 9:3; 17:3; AcPl BMM verso 37 (diferente em AcPl Ha 8, 29). Ele é também o κύριος, «Senhor», a que D 14:3 se refere ao citar β. μέγας, «grande rei», de Ml 1:14; para essa expressão, ver também AcPl Ha 9:1s. (compare 9:7). Compare Mt 21:5 (Zc 9:9); 25:34, 40; Jo 18:37 (pergunta do magistrado: βασιλεὺς εἶ σύ;, «és tu rei?»; compare Μαρτύριον Κάρπου 24 (Martyr. Carpi), em Musurillo, Acts of the Christian Martyrs, p. 24: βουλευτὴς εἶ;). β. βασιλέων, «rei dos reis» (como 2Mc 13:4; Fílon, Spec. Leg. 1:18; Decal. 41; compare PGM 13, 605; de Zeus, Dião Crisóstomo 2, 75), Ap 17:14; 19:16 (G. Beale, NTS 31, 1985, 618–20, com referência a Dn 4:37; em apoio, T. Slater, NTS 39, 1993, 159s.). O título ainda era corrente para reis na era cristã primitiva (Deissmann, LO 310s. [LAE 367s.]; Diodoro Sículo 1, 47, 4, antiga inscrição régia: β. βασιλέων; 1, 55, 7: β. βασιλέων καὶ δεσπότης δεσποτῶν Σεσόωσις; Mêmnon [século I a.C./I d.C.] 434 Fgm. 1, 31, 3 Jac.: βας. βας. de Tigranes; Apiano, Bell. Civ. 2, 67 §278; Ez 26:7; Dn 2:37; 2Esd 7:12; Mussies 96s.; W. Huss, Der «König der Könige» und der «Herr der Könige», ZDPV 93, 1977, 131–40) e foi deliberadamente reservado pelos cristãos a seu Senhor, em forte contraste com os reis terrenos (compare Pass. Scilit. 6, p. 24 v. Gebh.). — B 11:5 (Is 33:17). ὁ β. τῶν οὐρανῶν, «rei dos céus», AcPl Ha 7, 29. <strong>b. De Deus</strong> (Platão, Ep. 2, 312e: ὁ πάντων βασιλεύς, «rei de tudo»; Plutarco, Mor. 383a: ἡγεμών ἐστι κ. βασιλεὺς ὁ θεός, de almas humanas que alcançaram a bem-aventurança eterna); μέγας β., «grande rei» (SEG VIII, 32, 3 [século III d.C.], de Zeus; Tb 13:16; Fílon, Migr. Abr. 146 e outros; SibOr 3, 499 e 616; de reis humanos desde Heródoto 1, 188, 1; Jt 2:5; 3:2; EpArist; Fílon), Mt 5:35 (compare Sl 47:3); Hv 3, 9, 8; β. τῶν ἐθνῶν, «rei das nações» (Jr 10:7; ver edição de H. Swete, variante), Ap 15:3; β. τῶν αἰώνων, «rei dos séculos» (Tb 13:7, 11; En 9:4; compare Sl 144:13; Êx 15:18; Josefo, Ant. 1, 272: δέσποτα παντὸς αἰῶνος, e 14:24: β. τῶν ὅλων [também título do deus Urano em Diodoro Sículo 3, 56, 5]; PGM 12, 247: αἰώνων βασιλεῦ καὶ κύριε), 1Tm 1:17; Ap 15:3, variante; ἐπουράνιος β. τῶν αἰ., «rei celestial dos séculos», 1Cl 61:2; β. τῶν βασιλευόντων, «rei dos que reinam», 1Tm 6:15 (como 3Mc 5:35, variante; Pel.-Leg. 21, 8; 24, 21); β. τῆς δόξης, «rei da glória», AcPl BMM verso 24; 26. — W. Graf Baudissin, Kyrios III, 1929, 70–76. <strong>c. De um rei dos espíritos no mundo inferior:</strong> Abadom, Ap 9:11. — W. Schubart, Das hell. Königsideal nach Inschr. u. Pap., APF 12, 1937, 1–26; P. Carlier, La royauté en Grèce avant Alexandre, 1984 (resumo e inscrições em SEG XXXIX, 1792). — B. 1321; 1324; M-M; TW; Sv.</p></section></article> <article id=\"entry-basileuo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βασιλεύω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦basileúō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro βασιλεύσω; primeiro aoristo ἐβασίλευσα; perfeito, terceira pessoa singular βεβασίλευκεν, 2Sm 5:10 (Homero e posteriores).<br/><strong>1. Exercer autoridade em nível régio: ser rei, reinar, governar</strong> (B-D-F §§177; 233, 2; 234, 5; Robinson 801, 833, 902). <strong>a. De governantes temporais:</strong> com genitivo τινός, «reinar sobre algo» (1Esd 1:37; 6:16; 1Mc 1:16; 11:9 e outros); τῆς Ἰουδαίας, «sobre a Judeia», Mt 2:22, de Arquelau, chamado rei sem deter oficialmente esse título (Josefo, Vi. 5: βασιλεύοντος Ἀρχελάου; Ant. 17, 188ss.; 317ss.; 18, 93: βασιλεὺς Ἀ.); τοῦ Ἰσραήλ, «de Israel», GJs 23:2; τῶν περάτων τῆς γῆς, «dos confins da terra», IRo 6:1; com ἐπί τινα, «sobre alguém» (Gn 37:8; 1Sm 8:9; 12:1 e outros), Lc 19:14, 27. βασιλεῖαι βασιλεύσουσιν ἐπὶ τ. γῆς, «poderes régios reinarão sobre a terra» (ver ἐπί 1a), B 4:4. Sobre βασιλεὺς τ. βασιλευόντων, 1Tm 6:15, ver βασιλεύς 2b. <strong>b. De Deus e dos que estão estreitamente unidos a ele:</strong> α. Deus (Pseudo-Focílides 111), Ap 11:17; 19:6 (ver abaixo a acepção 2 para interpretação diferente de ambas as passagens); β. Cristo, Lc 1:33; 1Co 15:25; εἰς τ. αἰῶνας, «para sempre», MPol 21; γ. Deus e Cristo juntos: sua βασιλεία … βασιλεύσει, «reino … reinará» (ver 1a, B 4:4), εἰς τ. αἰῶνας τ. αἰώνων, «para todo o sempre» (compare Sl 9:37), Ap 11:15; δ. os cristãos fiéis, chamados a reinar com Deus, Rm 5:17b; Ap 5:10 (ἐπὶ τ. γῆς, como em 1a); 20:4, 6; 22:5 (compare Dn 7:27). <strong>c. Figuradamente:</strong> a morte, Rm 5:14 (ἐπί τινα), 17a; o pecado, versículo 21a; a graça, 21b; o desejo pecaminoso, Rm 6:12.<br/><strong>2. Obter poder régio: tornar-se rei</strong>, especialmente no aoristo (Heródoto 1, 130, 1; Tucídides 2, 99, 3; Políbio 5, 40, 6; 2Rs 14:29; 15:1, 7, 10; 1Mc 1:10 e outros), Ap 11:17; 19:6 (sobre ambos, ver 1bα); GHb 70, 16–18; Ox 654, 8 (GTh 2). χωρὶς ἡμῶν ἐβασιλεύσατε, «sem nós vos tornastes reis», 1Co 4:8 (em Apiano, Basil. 1a §5, βασιλεύω significa «apoderar-se do governo»). — DELG; M-M; TW; Spicq.</p></section></article> <article id=\"entry-basilikos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βασιλικός, ή, όν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦basilikós⟧</span><span class=\"separator\">·</span><span>adjetivo; substantivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ésquilo, Heródoto e posteriores.) <strong>Real, régio</strong>; de vestimenta oficial do rei (ChronLind C 89: τὰν βασιλικὰν στολάν; Et 8:15): ἐσθὴς β., «veste régia» (compare Diodoro Sículo 17, 47, 4; 17, 116, 2 e 3), At 12:21 (descrita em Josefo, Ant. 19, 344). νόμος β., «lei real», assim chamada por sua importância transcendente (de certo modo como Pseudo-Platão, Minos 317c: τὸ μὲν ὀρθὸν νόμος ἐστὶ βασιλικός; Epicteto 4, 6, 20; Fílon, Poster. Cai. 101; 102; 4Mc 14:2) ou, mais provavelmente, por ser dada pelo rei (do reino de Deus), Tg 2:8 (compare OGI 483, 1: ὁ βας. νόμος; BGU 820, 2; 1074, 15; 1Esd 8:24; 2Mc 3:13). χώρα β., «território do rei», At 12:20 (OGI 221, 41; 68). κατὰ τὴν βασιλικήν, «pela estrada real», AcPl Ant 13:20 (compare Aa I, 237, 4). τὸ κεφαλοδέσμιον … χαρακτῆρα ἔχει βασιλικόν, «a faixa da cabeça traz uma marca real», GJs 2:2. — O β., em Jo 4:46, 49, poderia ser parente da família régia (herodiana) (Luciano, Dial. Deor. 20, 1; Pseudo-Luciano, De Salt. 8; Plutarco, Mor. 546e), mas é mais provável que designe <strong>funcionário régio</strong> (não necessariamente judeu: A. Mead, JSNT 23, 1985, 69–72; talvez «conselheiro»: G. Schwartz, ZNW 75, p. 138 [tradução aramaica]); referências nos comentários. Em Apiano, Mithrid. 80 §358, οἱ βασιλικοί são os soldados do rei Mitrídates. — DELG, s.v. βασιλεύς; M-M; TW; Spicq; Sv.</p></section></article> <article id=\"entry-basiliskos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βασιλίσκος, ου, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦basilískos⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Políbio 3, 44, 5; Plutarco, Mor. 1d, variante de leitura; Ateneu 13, 20, p. 566b; OGI 200, 18; POxy 1566, 9; Sb 6949, 18 e 28; TestAbr A.) Diminutivo de βασιλεύς: <strong>reizinho, pequeno rei</strong>, variante de leitura em Jo 4:46, 49. — DELG, s.v. βασιλεύς.</p></section></article> <article id=\"entry-basilissa-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βασίλισσα, ης, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦basílissa⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Em lugar das formas áticas βασιλίς [τῇ βασιλίδι Ῥώμῃ, Justino, A I, 26, 2; 56, 2] e βασίλεια [Frínico, p. 225 Lob.; Méris 192]; primeiramente em Alceu Cômico [séculos V/IV a.C.] 6 e Xenofonte, Oec. 9, 15; posteriormente frequente, inclusive em inscrições [índices de SIG e OGI; Meisterhans–Schwyzer 101, 5; Schweizer 140; Nachmanson 121]; papiros [Mayser 214; 222; 255]; APF 2, 1903, 541; 6, 1920, 453; Septuaginta; TestSol; JosAs; EpArist 41; Fílon, Congr. Erud. Gr. 45; Josefo, Bell. 1, 76; Ant. 11, 190 e outros; Taciano 33, 3.) <strong>Governante feminina de um território específico, com autoridade para transmitir o poder a um sucessor: rainha</strong>, Mt 12:42; Lc 11:31 (TestSol 19:3; 21:1); At 8:27; Ap 18:7. — DELG, s.v. βασιλεύς; M-M; TW.</p></section></article> <article id=\"entry-basis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βάσις, εως, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦básis⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver βαίνω; Ésquilo e outros; inscrições; papiros [PGM 7, 518]; Septuaginta; TestSol; EpArist; Fílon; Josefo; SibOr 5, 54; empréstimo na literatura rabínica.) Diversos sentidos relacionados com «passo»; na literatura examinada, <strong>aquilo com que se dá um passo; pé</strong>, normalmente a região abaixo do tornozelo (assim desde Platão, Tim. 92a; Diodoro Sículo 3, 28, 2; uso médico em Hobart 34s.; Fílon, Op. M. 118: διτταὶ χεῖρες διτταὶ βάσεις, «duas mãos e dois pés»; Poster. Cai. 3; Josefo, Ant. 7, 113; 303 [com χεῖρες]; Sb 13:18), αἱ β., «os pés», At 3:7. Sinônimo ποῦς. — DELG, s.v. βαίνω, p. 156; M-M.</p></section></article> <article id=\"entry-baskaino-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βασκαίνω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦baskaínō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro, terceira pessoa singular βασκανεῖ, Dt 28:56; primeiro aoristo ἐβάσκανα, ver B-D-F §72 (ver os dois verbetes seguintes; IG XII/7, 106 [século VI a.C.]; Eufórion [?], fragmento 175, 2, Coll. Alex., p. 58; Aristóteles e outros; Septuaginta; TestSol 18:39 [compare PVindobBosw 18, 39: [β]ασκένω]).<br/><strong>1. Exercer influência maléfica pelo olhar: enfeitiçar, afetar pelo mau-olhado</strong>, τινά, «alguém» (Aristóteles, Probl. 34, 20 [926b, 24]: με; Diodoro Sículo 4, 6, 4; Alexandre de Afrodísias, Probl. 2, 53: παῖδας; Dt 28:56; TestSol 18:39); provavelmente metaforicamente em Gl 3:1 (poder-se-ia afastar a βασκανία cuspindo três vezes: ὡς μὴ βασκανθῶ τρὶς ἔπτυσα, Teócrito 6, 39; ver ἐκπτύω em Gl 4:14; πτύω em Mc 8:23). Compare o adjetivo ἀβάσκαντος, POxy 3312, 3. — Literatura sobre o «mau-olhado»: J. H. Elliott, Biblical Interpretation 2/1, 1994, 80–84; S. Eitrem, SymbOsl 7, 1928, 73, nota 5 (bibliografia); M. Dickie, Heliodorus and Plutarch on the Evil Eye, ClPh 86, 1991, 17–29; idem, Glotta 71, 1993, 174–77.<br/><strong>2. Ressentir-se de algo desfrutado por outra pessoa: invejar</strong> (Demóstenes 20, 24; Teócrito 5, 13; Josefo, Vi. 425; C. Ap. 1, 2), com τινί, «de alguém» (Demóstenes 20, 24), ou τινά, «alguém» (Demóstenes 8, 19; Dt 28:54, 56; Sir 14:6, 8); οὐδέποτε ἐβασκάνατε οὐδένι, «jamais invejastes ninguém (pela oportunidade de dar testemunho até a morte)», IRo 3:1. — Sobre a associação entre inveja e mau-olhado, ver Elliott (acima, acepção 1), The Fear of the Leer, the Evil Eye from the Bible to Li’l Abner, Forum 4/4, 1988, 42–71. — B. 1495; M-M (latim <em>fascinum</em>); TW; Spicq.</p></section></article> <article id=\"entry-baskania-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βασκανία, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦baskanía⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver βασκαίνω; Platão, Demóstenes e outros.) <strong>Inveja</strong> (Dião Crisóstomo 28 [45], 5; Vi. Aesopi W 16 P.; 4Mc 1:26; 2:15; TestIss 4:5; Fílon; Josefo, Ant. 3, 268), IRo 7:2. — Welles, p. 321; M-M, s.v. βασκαίνω.</p></section></article> <article id=\"entry-baskanos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βάσκανος, ου, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦báskanos⟧</span><span class=\"separator\">·</span><span>substantivo masculino; adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver os dois verbetes anteriores; como substantivo e adjetivo, Demóstenes e outros; referências epigráficas em SEG XLI, 1526; Fílon, In Flacc. 29; Josefo, Ant. 6, 59; TestIss 3:3; 4:5, variante; Melitão, HE 4, 26, 9.) <strong>Pessoa invejosa, invejoso</strong> (como substantivo, por exemplo, Demóstenes 18, 132; Menandro, Per. 529 S. = 279 Kö.; numa figura de argila, Sb 6295; Vécio Valente 2, 2; 358, 5; Sir 18:18; 37:11; Josefo, Bell. 1, 208), com ἀντίζηλος, πονηρός, MPol 17:1. — Ver φθόνος; DELG; Sv.</p></section></article> <article id=\"entry-bassos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Βάσσος, ου, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Bássos⟧</span><span class=\"separator\">·</span><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><strong>Basso</strong>, dirigente de uma congregação em Magnésia, IMg 2. O nome não é raro na Ásia Menor ocidental (CIG II, 3112b, 1; 3148, 4; 3151, 13; 3493, 23; IPergamon 361; 362, 2 e frequentes outras ocorrências) e é encontrado especificamente em Magnésia (IMagnMai 122g, 5; moedas, ibidem, p. xxiv).</p></section></article> <article id=\"entry-bastazo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βαστάζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦bastázō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro βαστάσω; primeiro aoristo ἐβάστασα (variante -ξα, Sir 6:25; AcPl Ha 8, 4; compare Sir 6:25; B-D-F §71). Homero e posteriores. Em todos os sentidos, com sugestão de um fardo.<br/><strong>1. Fazer algo subir a posição mais elevada: levantar, erguer, apanhar</strong> (Josefo, Ant. 7, 284: β. τ. μάχαιραν ἀπὸ τ. γῆς, «erguer a espada do chão»); pedras, Jo 10:31 (compare 8:59).<br/><strong>2. Sustentar um fardo: carregar, levar, suportar.</strong> <strong>a. Objeto físico:</strong> Hs 9, 2, 4; AcPl Ha 8, 4; jarro de água, Mc 14:13; Lc 22:10; esquife, Lc 7:14, compare 1Cl 25:3; pedras, Hs 9, 3, 4s.; 9, 4, 1 (absoluto); 3; 9, 6, 7; <strong>sustentar:</strong> o céu, Hs 9, 2, 5; πύργον, «torre», 9, 4, 2; κόσμον, «mundo», 9, 14, 5. Uma cruz, Jo 19:17 (Cáriton 4, 2, 7; 4, 3, 10: σταυρὸν ἐβάστασα, «carreguei uma cruz»; Artemidoro 2, 56: σταυρὸν β.); acerca de substâncias medicinais usadas para fins mágicos, φάρμακα εἰς τὰς πυξίδας β., «transportar drogas em caixas», Hv 3, 9, 7; acerca de animais empregados para montaria, Ap 17:7 (compare Epicteto 2, 8, 7). Passivo: Hv 3, 8, 2; Hs 9, 4, 3; 9, 6, 7; 9, 14, 5 (ver 9, 24, 6 quanto à interpretação: aqueles que levam alegremente o nome do Filho de Deus são por ele levados). De pessoas carregadas, At 3:2; 21:35; GJs 20:3 (não é papiro). Especialmente de mulheres grávidas: ἡ κοιλία ἡ βαστάσασά σε, «o ventre que te carregou», Lc 11:27. — Lc 10:4; Rm 11:18; B 7:8. O sentido de AcPl Ha 2, 4 é incerto por causa do contexto fragmentário.<br/><strong>b. Figuradamente, como extensão de 2a:</strong> <strong>α. Suportar algo oneroso</strong> (2Rs 18:14; Sir 6:25): uma cruz, seguindo Jesus em seu sofrimento, Lc 14:27; exigências legais, At 15:10 (J. Nolland, NTS 27, 1980, 113–15); ζυγὸν τοῦ κυρίου, «jugo do Senhor», conduta cristã, D 6:2; ἀλλήλων τὰ βάρη βαστάζετε, «levai as cargas uns dos outros», Gl 6:2; compare versículo 5. <strong>β. Ser capaz de resistir a circunstâncias especialmente difíceis ou opressivas: suportar, aguentar</strong> (Epicteto 1, 3, 2; Ench. 29, 5; Esopo, Fab. 391 P., infortúnio e dificuldade; PBrem 36, 8s. [Mitt-Wilck. I/2, 352]: οὐ βαστάζουσι τοσοῦτο τέλεσμα; Jó 21:3, variante de leitura): o fardo e o calor do dia, Mt 20:12; κακούς, «maus», Ap 2:2; δύνασθαι β., «ser capaz de suportar», palavras relacionadas a mistérios divinos, Jo 16:12; Hv 1, 3, 3. <strong>Suportar pacientemente, tolerar:</strong> as fraquezas dos fracos, Rm 15:1; compare IPol 1:2; o mal, Ap 2:3; κρίμα, «suportar o próprio juízo», isto é, pagar a pena, Gl 5:10. ὸ̔ δύνασαι βάστασον, «tolera ou aceita aquilo que puderes», D 6:3 (conselho relativo a restrições alimentares, seguido de advertência contra comer alimentos oferecidos em ambiente politeísta). <strong>c. Sem ideia de tensão externa ou interna: carregar, trazer</strong> marcas, Gl 6:17 (ver Deissmann, B 265ss. [BS 352ss.]); o nome (mensagem) de Jesus: β. τὸ ὄνομά μου ἐνώπιον ἐθνῶν, «levar o meu nome diante das nações», At 9:15 (compare POxy 1242 I, 17, onde gentios e judeus alexandrinos comparecem diante de Trajano: ἕκαστοι βαστάζοντες τ. ἰδίους θεούς, «cada qual trazendo seus próprios deuses»); Hs 8, 10, 3; 9, 28, 5.<br/><strong>3. Levar alguma coisa, frequentemente onerosa, para fora de um lugar: levar embora, remover</strong> (PFay 122, 6 [cerca de 100 d.C.]; Bel 36, Teodocião). <strong>a. Sem implicação moral:</strong> um cadáver (Josefo, Ant. 3, 210; 7, 287; POxy 2341, 8), Jo 20:15; de sandálias, «retirar», Mt 3:11 (compare PGM 4, 1058: βαστάξας τὸ στεφάνιον ἀπὸ τ. κεφαλῆς; N. Krieger, Barfuss Busse Tun, NovT 1, 1956, 227s.); de doença, «remover» (Galeno, De Compos. Medic. Per Gen. 2, 14, citando o médico Asclepíades do século I: ψώρας τε θεραπεύει καὶ ὑπώπια βαστάζει; ver também Rydbeck, Fachprosa, 1967, 155s.), Mt 8:17; IPol 1:3 (a menos que esta passagem pertença à acepção 2bα). <strong>b. Com implicação moral: tomar furtivamente, surrupiar, roubar</strong> (Políbio 32, 15, 4; Diógenes Laércio 4, 59; Josefo, Ant. 1, 316; 7, 393; PTebt 330, 7; BGU 46, 10; 157, 8; PFay 108, 16; POxy 69, 4), Jo 12:6. — B. 707; DELG; M-M; TW.</p></section></article> <article id=\"entry-batos-i-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βάτος, ου, ἡ, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦bátos⟧</span><span class=\"separator\">·</span><span>substantivo feminino ou masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Segundo Méris 99, o feminino é helenístico [Justino, D. 60, 3; 127, 4; 128, 1] e ὁ βάτος, como em Mc 12:26; Êx 3:2–4 [Justino, D. 60, 4] e Fílon, Mos. 1, 67, é ático; Thackeray e P. Katz, ZNW 46, 1955, 136, nota 8a [ver B-D-F §49, 1], demonstram, porém, que o inverso é verdadeiro. — Homero e outros; Kaibel 546, 6; 548, 2; Septuaginta; Justino.) <strong>Arbusto espinhoso do gênero Rubus: sarça</strong>, acerca do arbusto no qual Moisés teve uma visão de Deus (Êx 3:2–4; compare Dt 33:16; Josefo, Ant. 2, 266), Mc 12:26 (ὁ); ἐπὶ τ. βάτου, «na passagem sobre a sarça», Lc 20:37 (ἡ); At 7:30, 35 (ἡ); ver Zohary 140s.; 1Cl 17:5 (ἡ). Símbolo de esterilidade, Lc 6:44 (compare Jó 31:40). Zohary 140s. identifica a sarça de Moisés como <em>Cassia senna</em>, arbusto que alcança um metro de altura, com folhagem espessa de folhas pinadas. — DELG; M-M; TW.</p></section></article> <article id=\"entry-batos-ii-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βάτος, ου, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦bátos⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><strong>Medida hebraica para líquidos, «bato», jarra</strong> (empréstimo do hebraico בַּת; compare 2Esd 7:22; En 10:19). Segundo Josefo, Ant. 8, 57, β. corresponde a 72 sextários, aproximadamente 34 litros (F. Hultsch, Griechische und römische Metrologie², 1882, 488:36, 371; O. Viedebannt, Forschungen zur Metrologie des Altertums, 1917, 127ss.: 32, 61), Lc 16:6 (variantes: βάδος, κάδος, κάβος). — DELG; M-M.</p></section></article> <article id=\"entry-batrachos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βάτραχος, ου, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦bátrachos⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Batr., Heródoto e outros; PGM 36, 324; 326; Septuaginta; Fílon; Josefo, Ant. 2, 296.) <strong>Rã</strong>, forma na qual apareceram os espíritos impuros, Ap 16:13 (Artemidoro 2, 15: βάτραχοι ἄνδρας γόητας προσαγορεύουσι, «rãs designam homens feiticeiros»). — F. Steinmetzer, D. Froschsymbol in Offb. 16, BZ 10, 1912, 252–60; DELG; M-M.</p></section></article> <article id=\"entry-battalogeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βατταλογέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦battalogéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(βαττολογέω, variante de leitura; ver Rdm. 44; Mlt-H. 272.) Primeiro aoristo, subjuntivo βατταλογήσω. Palavra onomatopaica: <strong>falar de modo semelhante ao padrão de quem gagueja; repetir as mesmas palavras muitas vezes, falar irrefletidamente, tagarelar</strong> (explicado por πολυλογία), Mt 6:7; Lc 11:2, códice D. Fora dos autores dependentes do Novo Testamento, o vocábulo foi encontrado somente em Vi. Aesopi W 109, onde Perry assinala a variante βατολογέω em lugar de βατταλογέω (ausente na passagem correspondente na edição Eberhard I, capítulo 26, p. 289, 9; mas Vi. Aesopi G 50 P. tem o substantivo βαττολογία, «fala tola», em contexto diferente), e em Simplício (cerca de 530 d.C.), Comm. in Epict., p. 91, 23, na grafia βαττολογέω, «tagarelar». Talvez seja uma forma híbrida que traduz o aramaico אמר בטלהא, «falar ociosamente» (B-D-F §40). Diferentemente, F. Busbby, ET 76, 1964, 26. — Ver DELG, s.v. βατταρίζω, para discussão desse tipo de vocábulo; M-M.</p></section></article>"};
